def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_me = me[-1]
    last_opp = opp[-1]

    # Endgame exploitation: against a sufficiently cooperative opponent,
    # take the last few rounds while it is still cheap.
    if n >= 96:
        if opp_d == 0:
            return 'D'
        if opp_c * 4 >= n * 3:
            return 'D'
        if opp_c * 2 >= n:
            return 'D'
        return 'D'

    # Very early: cooperate, but answer immediate exploitation.
    if n < 5:
        if n == 1:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Count recent behavior.
    recent_len = 6
    recent = opp[-recent_len:]
    rec_c = recent.count('C')
    rec_d = recent_len - rec_c

    # Detect unconditional / near-unconditional defector.
    if opp_d * 4 >= n * 3 and rec_c <= 1:
        return 'D'
    if opp_c == 0:
        return 'D'

    # Detect unconditional / near-unconditional cooperator.
    if opp_d == 0:
        # Exploit only mildly until the endgame, to avoid triggering
        # conditional opponents that were merely patient.
        if n >= 80 and rng.random() < 0.5:
            return 'D'
        return 'C'
    if opp_d == 1 and opp_c >= 12:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Long mutual cooperation: keep it, with rare probes.
    if rec_c == recent_len:
        if rng.random() < 0.04:
            return 'D'
        return 'C'
    if rec_c >= recent_len - 1:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    # Strong recent defection: retaliate, but forgive if opponent shows
    # signs of returning to cooperation.
    if rec_d >= 4:
        if last_opp == 'C' and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Moderate recent defection.
    if rec_d == 3:
        if last_opp == 'D':
            return 'D'
        return 'C' if rng.random() < 0.5 else 'D'

    # Low recent defection.
    if rec_d <= 2:
        if last_opp == 'D':
            # Punish once, but avoid long feuds.
            if last_me == 'D':
                return 'C'
            return 'D'
        return 'C'

    # Fallback: generous tit-for-tat weighted by overall cooperation.
    if opp_c * 2 >= n:
        if last_opp == 'D' and rng.random() < 0.5:
            return 'D'
        return 'C'
    if last_opp == 'C':
        return 'C' if rng.random() < 0.6 else 'D'
    return 'D'
